solution:
body { margin: 0; font: 1rem/1.5 sans-serif; }
.tableau {
  --espace: 16px;
  --surface: #ffffff;
  --texte: #172a3a;
  --accent: #164e63;
  --ligne: #475569;
  --focus: #9a3412;
  display: grid;
  gap: var(--espace);
  padding: var(--espace);
  color: var(--texte);
  background-color: var(--surface);
}
.tableau[data-theme="sombre"] {
  --surface: #172a3a;
  --texte: #f8fafc;
  --accent: #bae6fd;
  --ligne: #94a3b8;
  --focus: #fbbf24;
}
.entete h1 {
  margin: 0;
  font-size: clamp(1.5rem, 1rem + 2.5vw, 2.5rem);
  line-height: 1.2;
}
.nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.nav a {
  display: block;
  padding: 12px 16px;
  color: var(--accent);
  border-bottom: 3px solid transparent;
}
.nav a[aria-current="page"] {
  font-weight: 700;
  border-bottom-color: var(--accent);
}
.cartes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: var(--espace);
}
.carte {
  min-width: 0;
  padding: var(--espace);
  border: 1px solid var(--ligne);
}
.bouton:disabled { border-style: dashed; }
.nav a:focus,
.bouton:focus {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
@media (min-width: 600px) {
  .entete {
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
}
